import{_ as i,o,c as a,ag as t}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-09-15（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-09-15.md","filePath":"topics/ai-system-architecture/science-daily-2026-09-15.md"}'),l={name:"topics/ai-system-architecture/science-daily-2026-09-15.md"};function r(c,e,n,s,d,u){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="科学日报-·-2026-09-15-ai-系统架构" tabindex="-1">科学日报 · 2026-09-15（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-09-15-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-09-15（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-15.md</code> — 第26期</p></blockquote><hr><h2 id="前沿模型物理强不强-专家重批发现评估-饱和失真-arxiv" tabindex="-1">前沿模型物理强不强？专家重批发现评估&quot;饱和失真&quot;（arXiv） <a class="header-anchor" href="#前沿模型物理强不强-专家重批发现评估-饱和失真-arxiv" aria-label="Permalink to &quot;前沿模型物理强不强？专家重批发现评估&quot;饱和失真&quot;（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-15.md</code> ｜ arXiv: 2609.13009</p></blockquote><ul><li>多个权威物理基准（如 Artificial Analysis Intelligence Index 2026）偏低分显示前沿 LLM 在高等物理上吃力，但物理学者实际使用体验与之不符。</li><li>方法：六个常用物理基准重测前沿模型 + 专家逐题<strong>审计题干/参考答案/模型输出</strong>，区分&quot;模型真错&quot; vs &quot;判卷错、参考答案错、题目含糊&quot;。</li><li>发现：多数被判错案例源于<strong>基准本身的问题</strong>而非模型物理推理缺陷；修正后分数线被实质抬升、接近饱和。</li><li>洞察：<strong>评估管线本身需要被审计</strong> —— 当模型&quot;卡在&quot;某个基准上，先怀疑判卷与参考答案，再谈模型能力。与&quot;AI 能力评估可信度&quot;主线强相关，也是物理×AI 的交叉点。</li></ul><h2 id="sqd-围绕次二次注意力做异构解聚推理-arxiv" tabindex="-1">SQD：围绕次二次注意力做异构解聚推理（arXiv） <a class="header-anchor" href="#sqd-围绕次二次注意力做异构解聚推理-arxiv" aria-label="Permalink to &quot;SQD：围绕次二次注意力做异构解聚推理（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-15.md</code> ｜ arXiv: 2609.13134</p></blockquote><ul><li>前沿模型加速采用次二次注意力（稀疏/线性/滑窗）以降内存与算力、保准确率；现有系统仍按稠密注意力为中心做解聚。</li><li>SQD：按&quot;二次 vs 次二次注意力&quot;而非算子类型切分解码，匹配各类变体的算术强度与内存足迹。稀疏：拆 top-k 选择（需索引完整 KV）与 top-k 注意力+FFN（静态内存）；线性/滑窗：拆稠密注意力层与次二次层+FFN。</li><li>8×B200 异构代理上吞吐与能效可观增益。</li><li>洞察：<strong>解聚维度从算子细化为注意力复杂度</strong> —— 为新架构（次二次注意力）专门设计系统，而非沿用稠密时代范式，是推理系统随模型结构演化的方向。</li></ul><h2 id="embodied-benchforge-闭环智能体流程自动构建具身基准-arxiv" tabindex="-1">Embodied-BenchForge：闭环智能体流程自动构建具身基准（arXiv） <a class="header-anchor" href="#embodied-benchforge-闭环智能体流程自动构建具身基准-arxiv" aria-label="Permalink to &quot;Embodied-BenchForge：闭环智能体流程自动构建具身基准（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-15.md</code> ｜ arXiv: 2609.13082</p></blockquote><ul><li>具身基准构建自动化仍停在孤立环节/特定环境；多步构建的中间产物常缺按产物粒度验证，局部缺陷沿依赖链扩散进最终基准。</li><li>Embodied-BenchForge = <strong>闭环基准合成</strong>：前向用可复用类型化技能编排可执行流程 + 产物依赖图记录中间输出；反向用按产物定制的契约驱动验证与修复，验证失败按<strong>溯源</strong>触发局部重执行或上游回滚。</li><li>构建了覆盖六个环境的基准。</li><li>洞察：把&quot;验证&quot;内建进<strong>生成依赖图</strong>、失败逐级回滚 —— 恰似软件的 CI/CD 移植到基准构建，让具身评估本身更可靠、可审计。呼应本主题 agent 工具链/评估治理。</li></ul><h2 id="广群化-rl-用局部对称性提升样本效率-arxiv" tabindex="-1">广群化 RL：用局部对称性提升样本效率（arXiv） <a class="header-anchor" href="#广群化-rl-用局部对称性提升样本效率-arxiv" aria-label="Permalink to &quot;广群化 RL：用局部对称性提升样本效率（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-15.md</code> ｜ arXiv: 2609.13035</p></blockquote><ul><li>现有方法多依赖固定群作用或预设状态抽象，经典 RL 又假设全局结构 MDP 与处处一致的转移，难以利用局部、状态依赖的规律。</li><li>用**广群（groupoid）**刻画局部状态依赖对称性，并在交互中动态发现等价结构：维护轨道代表元 + 转运子把原始状态映射到规范形 → 在对称性约化空间学习并保留局部区分。</li><li>实验：在具强部分对称性的稠密/大规模环境中显著提升样本效率与收敛，优于标准 Q-学习基线。</li><li>洞察：<strong>从全局群到局部广群</strong> —— 对称性不该是&quot;处处可用&quot;的假设，而应随交互被发现。是表征学习/RL 理论的一个干净推广。</li></ul><h2 id="seqmoe-预测-图兼容卸载逼近全载性能-arxiv" tabindex="-1">SeqMoE：预测+图兼容卸载逼近全载性能（arXiv） <a class="header-anchor" href="#seqmoe-预测-图兼容卸载逼近全载性能-arxiv" aria-label="Permalink to &quot;SeqMoE：预测+图兼容卸载逼近全载性能（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-15.md</code> ｜ arXiv: 2609.12978</p></blockquote><ul><li>MoE 结构优势 = 只需少量激活专家常驻内存；只要加载及时，卸载理论上可逼近全载性能，但实践难兑现。</li><li>SeqMoE：① 把<strong>专家激活预测重铸为序列建模</strong>（可多步多层前瞻）；② 预取调度形式化为带截止日期的排序问题，最大化命中+带宽；③ 基于预测的缓存用概率 Belady 策略做未来感知逐出；④ <strong>图兼容卸载运行时</strong>消除执行瓶颈。</li><li>洞察：MoE 卸载从&quot;负载不均的权宜之计&quot;走向<strong>接近全载性能的系统工程</strong> —— 预测驱动的缓存/预取是本主题&quot;省显存放更多模型&quot;主线的重要一页。</li></ul>',18)])])}const b=i(l,[["render",r]]);export{h as __pageData,b as default};
